#include <vector>
using namespace std;

class Solution {
public:
    vector<double> getCollisionTimes(vector<vector<int>>& cars) {
        int n = cars.size();
        vector<double> ans(n, -1.0);
        vector<int> st;

        for (int i = n - 1; i >= 0; --i) {
            int p1 = cars[i][0], s1 = cars[i][1];
            while (!st.empty()) {
                int j = st.back();
                int p2 = cars[j][0], s2 = cars[j][1];
                if (s1 <= s2) {
                    st.pop_back();
                } else {
                    double t = (double)(p2 - p1) / (s1 - s2);
                    if (ans[j] > 0 && t >= ans[j]) {
                        st.pop_back();
                    } else {
                        ans[i] = t;
                        break;
                    }
                }
            }
            st.push_back(i);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public double[] getCollisionTimes(int[][] cars) {
        int n = cars.length;
        double[] ans = new double[n];
        Arrays.fill(ans, -1.0);
        int[] st = new int[n];
        int top = 0;

        for (int i = n - 1; i >= 0; --i) {
            int p1 = cars[i][0], s1 = cars[i][1];
            while (top > 0) {
                int j = st[top - 1];
                int p2 = cars[j][0], s2 = cars[j][1];
                if (s1 <= s2) {
                    top--;
                } else {
                    double t = (double)(p2 - p1) / (s1 - s2);
                    if (ans[j] > 0 && t >= ans[j]) {
                        top--;
                    } else {
                        ans[i] = t;
                        break;
                    }
                }
            }
            st[top++] = i;
        }
        return ans;
    }
}

