var getCollisionTimes = function(cars) {
    const n = cars.length;
    const ans = Array(n).fill(-1.0);
    const stack = [];

    for (let i = n - 1; i >= 0; --i) {
        const [p1, s1] = cars[i];
        while (stack.length > 0) {
            const j = stack[stack.length - 1];
            const [p2, s2] = cars[j];
            if (s1 <= s2) {
                stack.pop();
            } else {
                const t = (p2 - p1) / (s1 - s2);
                if (ans[j] > 0 && t >= ans[j]) {
                    stack.pop();
                } else {
                    ans[i] = t;
                    break;
                }
            }
        }
        stack.push(i);
    }
    return ans;
};
